# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    import argparse

    parser = argparse.ArgumentParser(
        description="Ütköző ötletek automatikus párosítása és konfliktus-lista generálása"
    )
    parser.add_argument(
        "--room-id", default="demo_room",
        help="Szoba azonosító (default: demo_room)"
    )
    parser.add_argument(
        "--input", default="",
        help="Bemeneti fájl (.json vagy .jsonl). Ha üres, demo adatokat használ."
    )
    parser.add_argument(
        "--output-dir", default="./output",
        help="Kimeneti könyvtár (default: ./output)"
    )
    parser.add_argument(
        "--threshold", type=float, default=20.0,
        help="Konfliktus küszöbérték (default: 20.0)"
    )
    parser.add_argument(
        "--all-pairs", action="store_true",
        help="Ne greedy párosítás — mutass minden konfliktuspárt"
    )
    parser.add_argument(
        "--print", action="store_true",
        help="Nyomtassa ki a riportot a képernyőre is"
    )

    args = parser.parse_args()

    # Load messages
    if args.input:
        if args.input.endswith('.jsonl'):
            messages = load_messages_from_jsonl(args.input)
        else:
            messages = load_messages_from_json(args.input)
        if not messages:
            print(f"Hiba: nem sikerült üzeneteket betölteni: {args.input}")
            sys.exit(1)
    else:
        print("[conflict_list] Nincs bemenet megadva — demo adatok használata.")
        messages = SAMPLE_MESSAGES

    report = generate_conflict_list(
        room_id=args.room_id,
        messages=messages,
        output_dir=args.output_dir,
        threshold=args.threshold,
        greedy=not args.all_pairs,
    )

    if args.print or not args.input:
        print()
        print(format_report_text(report))

if __name__ == "__main__":
    main()